mapper.select:
select route_id as routeId, route_nm as routeNm, esttn_nm as esttnNm, route_tp as routeTp from busroutedb.ms_route where 1=1
and route_tp = #{routeTp}
order by route_nm, route_id

select count(*)
from busroutedb.ms_route
where 1=1

	and route_id = #{routeId}


	and route_tp = #{routeTp}

select route_id as routeId, route_ver as routeVer, route_nm as routeNm, route_tp as routeTp, fircar_tm as fircarTm, lstcar_tm as lstcarTm, caralc, fircar_tm_s as fircarTmS, lstcar_tm_s as lstcarTmS, caralc_s as caralcS, fircar_tm_h as fircarTmH, lstcar_tm_h as lstcarTmH, caralc_h as caralcH, ssttn_nm as ssttnNm, esttn_nm as esttnNm, use_at as useAt from busroutedb.ms_route where 1=1
and route_id = #{routeId}
and route_tp = #{routeTp}
order by route_tp, route_nm, route_id limit #{size} offset #{offset}

mapper.update:
update busroutedb.ms_route
set use_at = #{useAt}
where route_id = #{routeId}

update busroutedb.ms_route
use_at = #{useAt}, route_tp = #{routeTp}, fircar_tm = #{fircarTm}, lstcar_tm = #{lstcarTm}, caralc = #{caralc}, fircar_tm_s = #{fircarTmS}, lstcar_tm_s = #{lstcarTmS}, caralc_s = #{caralcS}, fircar_tm_h = #{fircarTmH}, lstcar_tm_h = #{lstcarTmH}, caralc_h = #{caralcH},
where route_id = #{routeId}

mapper.select:
select veh_id as vehId, veh_no as vehNo from busroutedb.ms_veh where 1=1
and group_id = #{groupId}
order by veh_no

select distinct maker_nm from busroutedb.ms_veh where 1=1
and group_id = #{groupId}
order by maker_nm

select count(*)
from busroutedb.ms_veh
where 1=1

		and group_id = #{groupId} 


		and veh_id = #{vehId}


		and maker_nm = #{makerNm}

select v.veh_id as vehId, v.veh_no as vehNo, v.group_id as groupId, o.group_nm as groupNm, v.vin, v.maker_nm as makerNm, v.model_nm as modelNm, v.model_year as modelYear, v.fuel_tp as fuelTp, v.lowfloor_yn as lowfloorYn, v.wheelchair_yn as wheelchairYn, v.oprat_at as opratAt, v.manager_nm as managerNm, v.manager_phone as managerPhone from busroutedb.ms_veh v left join smartbusmngdb.sbm_operator o on o.group_id = v.group_id where 1=1
and v.group_id = #{groupId}
and v.veh_id = #{vehId}
and v.maker_nm = #{makerNm}
order by v.veh_no limit #{size} offset #{offset}

select count(*)
from busroutedb.ms_veh
where group_id = #{groupId}
	and veh_no = #{vehNo}

select count(*) from smartbusmngdb.sbm_bus_drivers where (accepted_yn is null or accepted_yn = 0)
and group_id = #{groupId}
and status = 0

select d.driver_id as driverId, d.driver_name as driverName, d.login_id as loginId, d.phone, d.email, d.group_id as groupId, o.group_nm as groupNm, d.status, d.accepted_yn as acceptedYn from smartbusmngdb.sbm_bus_drivers d left join smartbusmngdb.sbm_operator o on o.group_id = d.group_id where (d.accepted_yn is null or d.accepted_yn = 0)
and d.group_id = #{groupId}
and d.status = 0

select count(*)
from smartbusmngdb.sbm_bus_drivers

	accepted_yn is not null and accepted_yn != 0  

		and group_id = #{groupId}


		and driver_name like concat('%', #{driverName}, '%')


		and status = #{status}

select d.driver_id as driverId, d.driver_name as driverName, d.login_id as loginId, d.phone, d.email, d.group_id as groupId, o.group_nm as groupNm, d.status, d.accepted_yn as acceptedYn, d.veh_no as vehNo, d.route_id as routeId, d.route_nm as routeNm, d.last_login_dt as lastLoginDt, d.created_dt as createdDt, d.accepted_dt as acceptedDt, d.accepted_by as acceptedBy from smartbusmngdb.sbm_bus_drivers d left join smartbusmngdb.sbm_operator o on o.group_id = d.group_id
d.accepted_yn is not null and d.accepted_yn != 0
and d.group_id = #{groupId}
and d.driver_name like concat('%', #{driverName}, '%')
and d.status = #{status}
order by d.updated_dt desc

mapper.update:
update smartbusmngdb.sbm_bus_drivers set accepted_yn = 1, accepted_dt = now(), accepted_by = #{writer}, status = 1, last_status_changed_at = now(), updated_dt = now(), updated_by = #{writer}, updated_with = 'WEB' where (accepted_yn is null or accepted_yn = 0) and status = 0
and group_id = #{groupId}
and driver_id in
#{id}

