select count(*)
from smartbusmngdb.sbm_bus_drivers
where login_id = #{loginId}

select d.driver_id as driverId, d.login_id as loginId, d.driver_name as driverName, d.phone, d.email, d.group_id as groupId, o.group_nm as groupNm, d.status, d.accepted_yn as acceptedYn, d.veh_id as vehId, d.veh_no as vehNo, d.route_id as routeId, d.route_nm as routeNm, d.route_tp as routeTp, d.last_login_dt as lastLoginDt, d.created_dt as createdDt, d.created_by as createdBy, d.updated_dt as updatedDt, d.updated_by as updatedBy, d.accepted_dt as acceptedDt, d.accepted_by as acceptedBy from smartbusmngdb.sbm_bus_drivers d left join smartbusmngdb.sbm_operator o on o.group_id = d.group_id where 1=1
and d.group_id = #{groupId}
and d.driver_id = #{driverId}

